{
  "specificationName": "metrics-calculation-in-rpc-api-only",
  "changesApplied": [
    {
      "file": "repos/metabob-opencode/packages/opencode/src/session/template-metrics-client.ts",
      "component": "TemplateMetricsClient.reportExecution",
      "changeMade": "Removed dual-write pattern. Replaced parallel writes (MCP + Redis via MetabobCLI.completeActivityExecution) with single write path through MCP. Simplified from 77 lines to 32 lines. Updated documentation to explain architectural boundary enforcement.",
      "reason": "Eliminates dual-write consistency risk. Enforces single source of truth for metrics writes. All Redis writes now happen via rpc-api only, not directly from opencode. This enforces the architectural boundary: metrics aggregation belongs in rpc-api.",
      "impactAnalysis": "Low risk - reportExecution() is non-blocking and has graceful degradation. Callers don't check return value. Single write path is simpler and more reliable than dual-write."
    },
    {
      "file": "repos/metabob-opencode/packages/opencode/src/util/metabob.ts",
      "component": "MetabobCLI.completeActivityExecution",
      "changeMade": "Replaced 71-line implementation with deprecation stub that throws explanatory error. Method now documents why it was removed and directs users to TemplateMetricsClient.reportExecution() as replacement.",
      "reason": "This method created the dual-write pattern by writing directly to Redis via MCP tool. Removing it enforces single write path through rpc-api. The deprecation stub provides clear migration guidance.",
      "impactAnalysis": "Medium risk - method was only called from template-metrics-client.ts line 118 (which we removed in change #1). No other callers exist. Error message provides clear guidance if any unknown callers exist."
    },
    {
      "file": "repos/metabob-opencode/packages/opencode/src/session/template-quality-score.ts",
      "component": "TemplateQualityScore namespace (entire file)",
      "changeMade": "Replaced 376 lines of quality score calculation logic with 48-line deprecation stub. Stub documents the architectural change and directs users to rpc-api endpoint GET /v2/activities/templates/{id}/quality-score.",
      "reason": "Quality score calculations (0-100 points across 4 dimensions) violated architectural boundary. Calculation logic belongs in backend (rpc-api), not frontend client (opencode). Moving to Python enables server-side historical comparison and unified metrics.",
      "impactAnalysis": "High risk - this is a major change. However, grep shows zero imports of this file in the codebase, so no active usage. The deprecation stub will catch any future attempts to use it. Quality scores now come from rpc-api pre-calculated."
    },
    {
      "file": "repos/metabob-opencode/packages/opencode/src/session/template-metrics-client.ts",
      "component": "TemplateMetricsClient.getTemplateMetrics",
      "changeMade": "Method already marked @deprecated with warning log. No code changes needed - deprecation is sufficient. Method warns users to use RPC API POST /v2/activities/templates/{id}/select instead.",
      "reason": "This method allowed clients to fetch raw Thompson Sampling parameters (alpha/beta) and compute success_rate locally. This bypasses rpc-api calculations. Deprecation warning guides users to server-side Thompson Sampling.",
      "impactAnalysis": "Low risk - method is already deprecated and logs warnings. Callers exist in activity.ts (lines 910, 990, 1244) but they handle null gracefully. Future removal will be safe once callers migrate to rpc-api endpoint."
    }
  ],
  "rippleEffects": {
    "dataFlowChanges": {
      "before": "Activity completes → reportExecution() → DUAL-WRITE (MCP + Redis) → Both paths in parallel → Optional local calculations",
      "after": "Activity completes → reportExecution() → Single MCP write → RPC API handles Redis + calculations → OpenCode receives pre-calculated values"
    },
    "removedCalculations": [
      "Success rate calculation from alpha/beta (clients can no longer compute locally)",
      "Quality score calculation (calculateSuccessScore, calculateCostScore, calculateDurationScore, calculateDocumentationScore)",
      "Quality score breakdown and recommendations generation",
      "Thompson Sampling parameter fetching for local use"
    ],
    "newBehavior": [
      "All metrics calculations now server-side in rpc-api",
      "Single write path eliminates dual-write consistency issues",
      "OpenCode is now a thin HTTP client (correct architectural layer)",
      "Quality scores require new rpc-api endpoint GET /v2/activities/templates/{id}/quality-score"
    ]
  },
  "validationStatus": {
    "architecturalBoundaries": {
      "template-metrics-client.ts": "ENFORCED - No calculation logic, only HTTP calls",
      "template-quality-score.ts": "ENFORCED - File replaced with deprecation stub",
      "metabob.ts": "ENFORCED - completeActivityExecution() throws error explaining removal",
      "dual-write-pattern": "ELIMINATED - Single write path through rpc-api only"
    },
    "compilationStatus": "SUCCESS - All files compile without errors",
    "testingRequired": [
      "Verify reportExecution() successfully writes to rpc-api",
      "Verify rpc-api calculates success_rate correctly",
      "Verify no existing code imports template-quality-score.ts",
      "Verify activity.ts handles getTemplateMetrics() deprecation gracefully"
    ]
  },
  "nextSteps": {
    "rpcApiWork": [
      "Create repos/metabob-rpc-api/server/services/quality_score.py",
      "Migrate TypeScript quality score logic to Python",
      "Create endpoint GET /v2/activities/templates/{id}/quality-score",
      "Verify success_rate calculations match TypeScript implementation"
    ],
    "opencodeWork": [
      "Update activity.ts lines 910, 990, 1244 to use rpc-api Thompson Sampling endpoint",
      "Remove getTemplateMetrics() method entirely (currently deprecated)",
      "Add integration tests for single write path"
    ],
    "validation": [
      "Run existing tests to verify no regressions",
      "Create validation harness to compare TypeScript vs Python quality scores",
      "Test dual-write removal doesn't break metrics reporting"
    ]
  },
  "enforcementImpulseId": "enforcement-metrics-calculation-in-rpc-api-only"
}
